這是一個簡單的 debounce 實作，支援 `leading`（立即執行第一次呼叫）與 `cancel()`：

```javascript
/**
 * 建立一個 debounce 包裝函式
 * @param {Function} fn - 要被防抖動的函式
 * @param {number} wait - 等待毫秒數
 * @param {Object} [options]
 * @param {boolean} [options.leading=false] - 是否在等待開始時立即執行
 * @returns {Function & { cancel: Function }}
 */
function debounce(fn, wait = 300, { leading = false } = {}) {
  let timer = null;

  function debounced(...args) {
    const callNow = leading && timer === null;

    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (!leading) fn.apply(this, args);
    }, wait);

    if (callNow) fn.apply(this, args);
  }

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}

// ===== 使用範例 =====

// 模擬搜尋輸入框
function search(keyword) {
  console.log(`搜尋：${keyword}`);
}

const debouncedSearch = debounce(search, 500);

// 快速連續呼叫，只有最後一次會在停止輸入 500ms 後執行
debouncedSearch('j');
debouncedSearch('ja');
debouncedSearch('jav');
debouncedSearch('java');
// 輸出（約 500ms 後）：搜尋：java

// 使用 leading 選項：第一次立即執行，之後的呼叫在停止 500ms 後才會再執行
const debouncedSave = debounce(() => console.log('已儲存'), 500, { leading: true });

debouncedSave(); // 立即輸出：已儲存
debouncedSave(); // 被忽略（等待中）

// 取消尚未執行的呼叫
debouncedSearch.cancel();
```

**重點說明：**
- 每次呼叫都會清除前一個計時器並重新計時，因此只有在「停止呼叫 `wait` 毫秒後」才會執行。
- `leading: true` 會在等待期開始時立即執行一次。
- `cancel()` 可取消尚未執行的呼叫，例如元件卸載時避免多餘的執行。

```javascript
function debounce(fn, delay = 300) {
  let timer = null;

  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => {
      fn.apply(this, args);
    }, delay);
  };
}
```

使用範例：

```javascript
const onSearch = debounce((keyword) => {
  console.log('搜尋：', keyword);
}, 500);

// 連續輸入時，只有最後一次輸入停止 500ms 後才會執行
onSearch('j');
onSearch('ja');
onSearch('jav');
onSearch('java');
// 輸出：搜尋： java
```

