/**
 * 防抖（debounce）：連續呼叫時，只有在最後一次呼叫後等待 wait 毫秒才會執行 fn。
 * @param {Function} fn 要防抖的函式
 * @param {number} wait 等待時間（毫秒）
 * @returns {Function} 防抖後的函式，附帶 cancel() 方法
 */
function debounce(fn, wait = 300) {
  let timer = null;

  function debounced(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      fn.apply(this, args);
    }, wait);
  }

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}

// 使用範例：搜尋框輸入時，停止打字 500 毫秒後才發送請求
const searchInput = document.querySelector('#search');

const handleSearch = debounce((event) => {
  console.log('搜尋關鍵字：', event.target.value);
}, 500);

searchInput.addEventListener('input', handleSearch);

// 若需要取消尚未執行的呼叫（例如元件卸載時）
// handleSearch.cancel();
```

重點：
- 每次呼叫都會清除前一次的計時器，所以只有最後一次呼叫會真正執行 `fn`。
- `this` 與參數會透過 `fn.apply` 保留，事件處理函式可以正常使用 `event.target`。
- `cancel()` 可以在不需要時取消等待中的執行。

```javascript
/**
 * 建立一個防抖（debounce）函式：在最後一次呼叫後等待 `delay` 毫秒才真正執行。
 * @param {Function} fn 要防抖的函式
 * @param {number} delay 等待時間（毫秒）
 * @returns {Function & { cancel: () => void }}
 */
function debounce(fn, delay) {
  let timer = null;

  function debounced(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      fn.apply(this, args);
    }, delay);
  }

  // 取消尚未執行的呼叫
  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}
```

## 使用範例

```javascript
// 模擬搜尋輸入：使用者停止輸入 300ms 後才送出請求
function search(keyword) {
  console.log(`搜尋：${keyword}`);
}

const debouncedSearch = debounce(search, 300);

debouncedSearch('a');
debouncedSearch('ab');
debouncedSearch('abc'); // 只有這次會在 300ms 後真正執行

// 輸出（約 300ms 後）：
// 搜尋：abc

// 取消尚未執行的呼叫
debouncedSearch('xyz');
debouncedSearch.cancel(); // 不會有任何輸出
```

### 瀏覽器中的實際用法

```html
<input id="box" placeholder="輸入關鍵字">
<script>
  // 假設 debounce 已定義於上方
  const input = document.getElementById('box');

  input.addEventListener('input', debounce(e => {
    console.log('送出搜尋：', e.target.value);
  }, 500));
</script>
```

### 說明
- **`clearTimeout`**：每次呼叫都會清掉前一個計時器，所以只有最後一次呼叫會生效。
- **`fn.apply(this, args)`**：保留原本的 `this` 與參數，因此可用於物件方法。
- **`cancel()`**：可在元件卸載或不再需要時取消待執行的呼叫，避免記憶體或邏輯錯誤。

```javascript
/**
 * 建立一個 debounce 函式：在最後一次呼叫後等待 `wait` 毫秒才執行。
 * @param {Function} fn - 要被防抖的函式
 * @param {number} wait - 等待時間（毫秒）
 * @returns {Function} 防抖後的函式，附帶 cancel() 方法
 */
function debounce(fn, wait = 300) {
  let timer = null;

  const debounced = function (...args) {
    const context = this;
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      fn.apply(context, args);
    }, wait);
  };

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}

// 使用範例
const onSearch = debounce((keyword) => {
  console.log('搜尋：', keyword);
}, 500);

onSearch('a');
onSearch('ab');
onSearch('abc');   // 只有最後一次會在 500ms 後執行
// 輸出：搜尋： abc

// 取消待執行的呼叫
onSearch('abcd');
onSearch.cancel(); // 不會有任何輸出
```

